import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.DgVVaeR-.js";const u=JSON.parse('{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装","frontmatter":{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装"},"headers":[],"relativePath":"dev/telemetry-spec.md","filePath":"dev/telemetry-spec.md","lastUpdated":1791090709000}'),c={name:"dev/telemetry-spec.md"};function i(r,e,l,s,n,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="テレメトリ-クラッシュハンドラー仕様" tabindex="-1">テレメトリ &amp; クラッシュハンドラー仕様 <a class="header-anchor" href="#テレメトリ-クラッシュハンドラー仕様" aria-label="Permalink to &quot;テレメトリ &amp; クラッシュハンドラー仕様&quot;">​</a></h1><hr><h2 id="sdk-動的制御-illustiaapplication" tabindex="-1">SDK 動的制御 (<code>IllustiaApplication</code>) <a class="header-anchor" href="#sdk-動的制御-illustiaapplication" aria-label="Permalink to &quot;SDK 動的制御 (`IllustiaApplication`)&quot;">​</a></h2><p><code>AppSettings.sendTelemetry</code>（デフォルト <code>false</code>）の値に基づき、GlitchTip 互換の Sentry Android SDK を動的に開始・停止します。</p><p>SDK の ContentProvider による自動初期化は <code>AndroidManifest.xml</code> の <code>io.sentry.auto-init=false</code> で無効化されています。ユーザーが明示的にオプトインした場合に限り <code>GlitchTipTelemetry</code> が SDK を初期化し、オプトアウト時は直ちに停止します。</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GlitchTipTelemetry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(applicationContext, settings.sendTelemetry)</span></span></code></pre></div><p>GlitchTip の DSN は <code>AndroidManifest.xml</code> に設定し、パフォーマンストレースはオプトイン時に 100%（<code>1.0</code>）サンプリングされます。GlitchTip が非対応の自動セッション追跡、既定 PII、Frame Metrics エンベロープは無効化されています。</p><h3 id="送信先" tabindex="-1">送信先 <a class="header-anchor" href="#送信先" aria-label="Permalink to &quot;送信先&quot;">​</a></h3><p>Android SDK は次の DSN を使用します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://b2607da9caa6433b8e0718ebb46d3a2f@glitchtip.yunfi.f5.si/1</span></span></code></pre></div><p>ホストは <code>glitchtip.yunfi.f5.si</code>、プロジェクト ID は <code>1</code> です。送信は従来どおりユーザーがテレメトリを有効化した場合に限ります。</p><h3 id="web-のセキュリティレポート送信先" tabindex="-1">Web のセキュリティレポート送信先 <a class="header-anchor" href="#web-のセキュリティレポート送信先" aria-label="Permalink to &quot;Web のセキュリティレポート送信先&quot;">​</a></h3><p>以下はブラウザーの CSP 違反レポート用の Security Endpoint です。Android SDK の DSN としては使用しません。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://glitchtip.yunfi.f5.si/api/1/security/?glitchtip_key=b2607da9caa6433b8e0718ebb46d3a2f</span></span></code></pre></div><p>Web サイトで利用する際は、配信サーバーの <code>Content-Security-Policy</code> または <code>Content-Security-Policy-Report-Only</code> HTTP ヘッダーの既存ポリシーに、次のディレクティブを追加します。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report-uri https://glitchtip.yunfi.f5.si/api/1/security/?glitchtip_key=b2607da9caa6433b8e0718ebb46d3a2f</span></span></code></pre></div><p>このリポジトリのドキュメント配信は静的ファイルを <code>gh-pages</code> に公開しており、HTTP レスポンスヘッダーの設定を管理していません。この URL の記載だけでブラウザーのレポート送信は有効になりません。配信サーバー側での設定が別途必要です。</p><p>参考: <a href="https://glitchtip.com/blog/2022-05-26-csp/" target="_blank" rel="noreferrer">GlitchTip の CSP レポート設定</a></p><hr><h2 id="ローカルクラッシュハンドラー-未捕獲例外送信-crashhandler" tabindex="-1">ローカルクラッシュハンドラー &amp; 未捕獲例外送信 (<code>CrashHandler</code>) <a class="header-anchor" href="#ローカルクラッシュハンドラー-未捕獲例外送信-crashhandler" aria-label="Permalink to &quot;ローカルクラッシュハンドラー &amp; 未捕獲例外送信 (`CrashHandler`)&quot;">​</a></h2><p><code>Thread.UncaughtExceptionHandler</code> を継承し、未捕獲例外発生時に以下の処理を行います：</p><ol><li>スタックトレースを解析し、リソース未検出 (<code>Resources.NotFoundException</code>) やドキュメントアクセス権限エラーを検知して原因に応じたトースト表示を試行。</li><li>テレメトリ有効時、<code>GlitchTipTelemetry.recordException(ex, tag = &quot;uncaught_crash&quot;)</code> によりクラッシュレポートを送信し、<code>GlitchTipTelemetry.flush()</code> で最大2秒の待機で送信キューのフラッシュを試行。</li></ol><hr><h2 id="非致命的例外-non-fatal-exceptions-の集約" tabindex="-1">非致命的例外（Non-fatal Exceptions）の集約 <a class="header-anchor" href="#非致命的例外-non-fatal-exceptions-の集約" aria-label="Permalink to &quot;非致命的例外（Non-fatal Exceptions）の集約&quot;">​</a></h2><p>各種 ViewModel、フィード読み込み、検索、詳細表示、ブックマーク、ダウンロード、PallaSync 同期処理などで発生した予期せぬ例外を <code>GlitchTipTelemetry.recordException(...)</code> で収集します。</p><ul><li><code>CancellationException</code>（コルーチンキャンセル）は自動的に除外されます。</li><li>モジュールタグ（<code>module</code>）および追加コンテキスト情報（クエリ、URL、作品IDなど）を付与して記録されます。</li><li><code>isSendDefaultPii = false</code> は呼び出し元が渡す <code>extras</code> の自動削除を意味しません。例えば検索失敗経路は検索語を渡しており、個人情報が一切含まれないとは保証できません。</li><li>プロセス終了前の送信はベストエフォートです。通信状態やOSによっては送信が完了しません。</li></ul><hr><h2 id="パフォーマンストレース" tabindex="-1">パフォーマンストレース <a class="header-anchor" href="#パフォーマンストレース" aria-label="Permalink to &quot;パフォーマンストレース&quot;">​</a></h2><p>GlitchTip は Sentry Envelope の <code>transaction</code> アイテムタイプを受け入れるため、Sentry Android SDK のパフォーマンス計測機能をそのまま利用できます。</p><h3 id="サンプリングレート" tabindex="-1">サンプリングレート <a class="header-anchor" href="#サンプリングレート" aria-label="Permalink to &quot;サンプリングレート&quot;">​</a></h3><p><code>AndroidManifest.xml</code> の <code>io.sentry.traces.sample-rate = 1.0</code>（100%）。</p><h3 id="計測トランザクション" tabindex="-1">計測トランザクション <a class="header-anchor" href="#計測トランザクション" aria-label="Permalink to &quot;計測トランザクション&quot;">​</a></h3><table tabindex="0"><thead><tr><th>トランザクション名</th><th>operation</th><th>計測範囲 / 説明</th></tr></thead><tbody><tr><td><code>app.startup</code></td><td><code>app.launch</code></td><td><code>IllustiaApplication.onCreate()</code> 内でテレメトリ有効化完了 〜 <code>startPostStartupWork()</code> 末尾</td></tr><tr><td><code>feed.home.load</code> / <code>feed.home.refresh</code></td><td><code>feed.home</code></td><td>ホームフィードの取得・復元・キャッシュ</td></tr><tr><td><code>feed.home.load_more</code></td><td><code>feed.home</code></td><td>ホームフィードの追加ページ取得</td></tr><tr><td><code>feed.ranking.refresh</code></td><td><code>feed.ranking</code></td><td>ランキング一覧の取得・更新</td></tr><tr><td><code>feed.ranking.load_more</code></td><td><code>feed.ranking</code></td><td>ランキング一覧の追加ページ取得</td></tr><tr><td><code>feed.timeline.refresh</code></td><td><code>feed.timeline</code></td><td>フォロー新着タイムラインの取得・更新</td></tr><tr><td><code>feed.timeline.load_more</code></td><td><code>feed.timeline</code></td><td>フォロー新着タイムラインの追加ページ取得</td></tr><tr><td><code>feed.watchlist.refresh</code></td><td><code>feed.watchlist</code></td><td>ウォッチリスト（タグ）の検索・取得</td></tr><tr><td><code>feed.watchlist.load_more</code></td><td><code>feed.watchlist</code></td><td>ウォッチリスト（タグ）の追加ページ取得</td></tr><tr><td><code>feed.novels.refresh</code></td><td><code>feed.novels</code></td><td>小説フィードの取得・更新</td></tr><tr><td><code>search.query</code></td><td><code>search</code></td><td>イラスト・マンガ・小説・ユーザーの複合検索</td></tr><tr><td><code>illust.detail.load</code></td><td><code>illust.detail</code></td><td>作品詳細、関連作品、コメント、投稿者情報の並行取得</td></tr><tr><td><code>user.profile.load</code></td><td><code>user.profile</code></td><td>ユーザー詳細プロファイルおよび投稿作品の並行取得</td></tr><tr><td><code>bookmarks.refresh</code> / <code>bookmarks.load_more</code></td><td><code>bookmarks</code></td><td>ブックマーク一覧の取得・追加読み込み</td></tr><tr><td><code>download.artwork</code></td><td><code>download</code></td><td>通常イラスト・マンガ画像の保存</td></tr><tr><td><code>ugoira.convert.gif</code></td><td><code>ugoira.convert</code></td><td>うごイラフレームの GIF エンコード処理</td></tr><tr><td><code>ugoira.convert.mp4</code></td><td><code>ugoira.convert</code></td><td>うごイラフレームの MP4 エンコード処理</td></tr><tr><td><code>pallasync.sync</code></td><td><code>sync.operation</code></td><td>PallaSync デバイス同期、アウトボックス送信、インボックス受信</td></tr></tbody></table><p><code>GlitchTipTelemetry.trace</code> / <code>GlitchTipTelemetry.traceAsync</code> はテレメトリが無効な場合にトランザクションを生成せずブロックを実行するため、呼び出し側で同意状態を別途確認する必要はありません。</p><h3 id="glitchtip-非対応のため無効化している機能" tabindex="-1">GlitchTip 非対応のため無効化している機能 <a class="header-anchor" href="#glitchtip-非対応のため無効化している機能" aria-label="Permalink to &quot;GlitchTip 非対応のため無効化している機能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>オプション</th><th>理由</th></tr></thead><tbody><tr><td><code>isEnableFramesTracking = false</code></td><td>GlitchTip が Frame Metrics エンベロープを処理しない</td></tr><tr><td><code>isEnablePerformanceV2 = false</code></td><td>Sentry 固有の拡張 API で GlitchTip 未対応</td></tr><tr><td><code>isEnableAutoSessionTracking = false</code></td><td>セッション追跡は GlitchTip 非対応</td></tr></tbody></table>',36)])])}const b=t(c,[["render",i]]);export{u as __pageData,b as default};
